insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('30bcb979-d7f2-4a66-be9c-04b6674fe4e4', 'f715edd7-050c-4d0b-9169-99f0accce93c', $$Bernhard Willems heeft een testament laten opmaken$$,
   $$bedrijfseconomie-havo-2022-i-bernhard-willems-context1.png$$,
   $$Bernhard Willems (98 jaar) vertelt zijn enige kind Victor dat hij op
12 juni 2020 een testament heeft laten opmaken. Bernhard is sinds enkele jaren weduwnaar.$$, 'inline'),
  ('8a0a73c3-22c8-4fd9-9e54-2141b9e032df', 'f715edd7-050c-4d0b-9169-99f0accce93c', $$kader: testament met erfstelling$$,
   $$bedrijfseconomie-havo-2022-i-bernhard-willems-context2.png$$,
   $$Testament
Vandaag, 12 juni 2020, verscheen voor mij, mr. Van der Laar, ………….. te Amsterdam: Bernhard Antoon Willems.
De verschenen persoon verklaarde de volgende beschikkingen te maken:
Erfstelling Ik benoem tot mijn erfgenamen, ieder voor een gelijk deel, mijn enig kind Victor Willems en de Stichting CliniClowns Nederland. Indien mijn kind tegelijk met mij of voor mij overlijdt of zijn erfdeel verwerpt, komt dat erfdeel eveneens toe aan de Stichting CliniClowns Nederland.$$, 'inline'),
  ('5cb0614c-3438-4b6c-a55c-502d6233008b', 'f715edd7-050c-4d0b-9169-99f0accce93c', $$Stichting CliniClowns: ANBI en beneficiair aanvaarden$$,
   $$bedrijfseconomie-havo-2022-i-bernhard-willems-context3.png$$,
   $$Zoon Victor (71 jaar) weet dat de Stichting CliniClowns is opgenomen in het testament. Hij wil graag weten waar CliniClowns het geld aan besteedt. Uit zijn onderzoek blijkt onder andere:
− De Stichting CliniClowns is een Algemeen Nut Beogende Instelling (ANBI) met als doel het bieden en bevorderen van afleiding, plezier en verlichting aan zieke, kwetsbare kinderen en volwassenen met een zorgbehoefte.
− In de statuten van de CliniClowns is opgenomen dat erfenissen alleen beneficiair worden aanvaard.$$, 'inline'),
  ('968e2aab-014d-4f86-a6b3-7984ef06d59e', 'f715edd7-050c-4d0b-9169-99f0accce93c', $$inleiding tarieven erfbelasting en vrijstelling$$,
   $$bedrijfseconomie-havo-2022-i-bernhard-willems-context4.png$$,
   $$Verder heeft Victor op de site van de Belastingdienst informatie gevonden over de tarieven van de erfbelasting en de hoogte van de vrijstelling.
Tarieven erfbelasting$$, 'inline'),
