  ('6ad73c29-534b-47b3-bd56-e105e1eff0e9', 'f715edd7-050c-4d0b-9169-99f0accce93c', $$verwachte totale erfenis € 450.000$$,
   $$bedrijfseconomie-havo-2022-i-bernhard-willems-context6.png$$,
