  ('a733e9ab-cfb6-4fb4-9b00-699771ecee41', 'fcf1c451-ace5-49d7-91cb-ef18eaa8b5a6', $$tabel maatregelen tweede en derde kwartaal 2020$$,
   $$bedrijfseconomie-havo-2022-i-restaurant-de-waal-context4.png$$,
