  ('8c2329c5-a811-4280-af0b-2ec4ab05281f', 'b32e4345-5041-403b-9816-d2d269a5b5bb', $$verwijzing naar informatiebron 5; certificaat wordt niet afgeschreven$$,
   $$bedrijfseconomie-havo-2022-i-ttime-context10.png$$,
   $$In informatiebron 5 staan de balans per 1 december 2021, de gedeeltelijk ingevulde winst- en verliesrekening en het liquiditeitsoverzicht over de maand december 2021. Op het certificaat van het keurmerk wordt niet afgeschreven.$$, 'inline'),
  ('b7a3dd25-3ac0-4ec4-9d86-dd50d4181a9e', 'b32e4345-5041-403b-9816-d2d269a5b5bb', $$Ttime voldoet aan stap 1 en 2$$,
